// Elige 1 tema y calcula el próximo día libre de publicación (12:00 Ecuador = 17:00 UTC)
const rows = $input.all().map(i => i.json);
const est = r => String(r.ESTADO_CORTO || '').toLowerCase().trim();
const HORA_UTC = 17;
const MAX_COLA_DIAS = 60;
const ahora = new Date();
let base = new Date(Date.UTC(ahora.getUTCFullYear(), ahora.getUTCMonth(), ahora.getUTCDate(), HORA_UTC));
if (base.getTime() - ahora.getTime() < 2 * 3600 * 1000) base = new Date(base.getTime() + 86400000);
const fechas = rows.map(r => new Date(r.PUBLICAR_EL || '')).filter(d => !isNaN(d));
const ultima = fechas.length ? new Date(Math.max(...fechas.map(d => d.getTime()))) : null;
let slot = base;
if (ultima && ultima.getTime() >= slot.getTime()) {
  slot = new Date(Date.UTC(ultima.getUTCFullYear(), ultima.getUTCMonth(), ultima.getUTCDate() + 1, HORA_UTC));
}
const programados = fechas.filter(d => d > ahora).length;
const disponibles = rows.filter(r => ['pendiente', 'procesando', 'renderizado'].includes(est(r)) && String(r.KEYWORD_PRINCIPAL || '').trim());
let elegido = null;
// Videos que YouTube rechazó por límite diario: se reintentan 1 vez cada 24 h (YT_REINTENTO)
const reintento = rows.find(r => est(r) === 'pendiente_youtube' && r.VIDEO_URL_CORTO && !(new Date(r.YT_REINTENTO || 0) > ahora)) || null;
if (reintento) elegido = reintento;
else if (programados < MAX_COLA_DIAS) {
  elegido = disponibles.find(r => est(r) === 'renderizado' && r.VIDEO_URL_CORTO) || disponibles.find(r => est(r) !== 'renderizado') || null;
}
if (reintento) slot = new Date(ahora.getTime() + 3600 * 1000); // publica 1 h después de subir
const es_reintento = !!reintento;
const maxId = Math.max(0, ...rows.map(r => parseInt(String(r.ID || '').replace(/\D/g, ''), 10) || 0));
return [{ json: {
  hay_tema: !!elegido,
  ya_renderizado: !!(elegido && ['renderizado', 'pendiente_youtube'].includes(est(elegido)) && elegido.VIDEO_URL_CORTO),
  es_reintento,
  necesita_temas: disponibles.filter(r => est(r) === 'pendiente').length < 6,
  ID: elegido ? elegido.ID : '',
  _keyword: elegido ? String(elegido.KEYWORD_PRINCIPAL).trim() : '',
  _ciudad: elegido ? (elegido.CIUDAD || 'Ventanas, Los Ríos') : '',
  _subtema: elegido ? (elegido.SUBTEMAS || '') : '',
  VIDEO_URL_CORTO: elegido ? (elegido.VIDEO_URL_CORTO || '') : '',
  TITULO_CORTO: elegido ? (elegido.TITULO_CORTO || '') : '',
  DESC_CORTO: elegido ? (elegido.DESC_CORTO || '') : '',
  TAGS_CORTO: elegido ? (elegido.TAGS_CORTO || '') : '',
  HASHTAGS_CORTO: elegido ? (elegido.HASHTAGS_CORTO || '') : '',
  existentes: rows.map(r => String(r.KEYWORD_PRINCIPAL || '').trim()).filter(Boolean),
  next_id: maxId + 1,
  slot_iso: slot.toISOString(),
  programados
}}];

const plan = $('🗓️ Planificar (tema + fecha)').first().json;
const d = $input.first().json;
let lista = d.temas || (typeof d.text === 'string' ? (JSON.parse(d.text).temas || []) : ((d.text && d.text.temas) || []));
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const STOP = new Set(['mi','tu','el','la','los','las','de','del','en','y','que','por','para','con','un','una','se','es','a','como','cuando','perro','perros','gato','gatos','hacer','sintomas','causas']);
const tokens = s => new Set(norm(s).split(' ').filter(w => w.length > 2 && !STOP.has(w)));
const parecido = (a, b) => { const A = tokens(a), B = tokens(b); if (!A.size || !B.size) return 0; let i = 0; for (const x of A) if (B.has(x)) i++; return i / Math.min(A.size, B.size); };
const usados = [...plan.existentes];
const out = [];
let id = plan.next_id;
for (const t of lista) {
  const kw = String(t.keyword || '').trim();
  if (!kw) continue;
  if (usados.some(u => norm(u) === norm(kw) || parecido(u, kw) >= 0.8)) continue;
  usados.push(kw);
  out.push({ json: { ID: 'V' + String(id++).padStart(3, '0'), ESTADO: 'pendiente', KEYWORD_PRINCIPAL: kw, CIUDAD: 'Ventanas, Los Ríos', SUBTEMAS: String(t.subtemas || ''), ESTADO_CORTO: 'pendiente' } });
}
return out;

// Sirve para videos recién renderizados y para los que quedaron pendientes de subir
const plan = $('🗓️ Planificar (tema + fecha)').first().json;
const src = plan.ya_renderizado ? plan : $('✅ Video renderizado').first().json;
return [{ json: { ID: plan.ID, VIDEO_URL_CORTO: src.VIDEO_URL_CORTO, TITULO: String(src.TITULO_CORTO || plan._keyword).slice(0, 88) + ' #Shorts',
  DESCRIPCION: (src.DESC_CORTO || '') + '\n\n💬 Únete a mi Comunidad de WhatsApp: https://chat.whatsapp.com/IkpYnlrPyEx8Y2NTyaFB6P\n🔗 Más artículos: https://www.veterinarioluis.com\n\n' + (src.HASHTAGS_CORTO || ''),
  TAGS: String(src.TAGS_CORTO || '').slice(0, 450), PUBLICAR_EL: plan.slot_iso } }];

const d = $input.first().json;
let g = Array.isArray(d.escenas) ? d : null;
if (!g) { let raw = d.text || d.output || ''; g = typeof raw === 'object' ? raw : JSON.parse(String(raw).replace(/^```json\s*/i,'').replace(/```\s*$/,'').trim()); }
let escenas = (g.escenas || []).filter(e => e && e.narracion);
const contar = arr => arr.reduce((n, e) => n + e.narracion.split(/\s+/).length, 0);
while (contar(escenas) > 115 && escenas.length > 4) escenas.splice(escenas.length - 2, 1);
const palabras = contar(escenas);
if (palabras < 60 || palabras > 125) throw new Error('Guion fuera de rango: ' + palabras + ' palabras');
const plan = $('🗓️ Planificar (tema + fecha)').first().json;
return [{ json: { ID: plan.ID, keyword: plan._keyword, titulo_video: String(g.titulo_video || plan._keyword).slice(0, 90),
  descripcion_seo: g.descripcion_seo || '', palabras_clave: g.palabras_clave || '', hashtags: g.hashtags || '', total_palabras: palabras, escenas } }];

// Imagen recortada exactamente a 1080x1920 para llenar toda la pantalla vertical
const fotos = $input.all();
const escenas = $('✂️ Separar escenas').all();
const usadas = new Set();
const out = [];
let conFoto = 0;
for (let i = 0; i < escenas.length; i++) {
  const esc = escenas[i].json.escena;
  const photos = (fotos[i] && fotos[i].json && fotos[i].json.photos) || [];
  const p = photos.find(x => !usadas.has(x.id)) || photos[0];
  let url = null;
  if (p) { usadas.add(p.id); url = p.src.original + '?auto=compress&cs=tinysrgb&fit=crop&w=1080&h=1920'; conFoto++; }
  else if (out.length) url = out[out.length - 1].imagen_url;
  out.push({ narracion: esc.narracion, imagen_url: url });
}
if (conFoto === 0) throw new Error('PEXELS no devolvió imágenes (revisa la clave de Pexels)');
for (let i = 0; i < out.length; i++) if (!out[i].imagen_url) out[i].imagen_url = out.find(e => e.imagen_url).imagen_url;
return [{ json: { ...$('📝 Validar guion').first().json, escenas: out } }];

const d = $input.first().json;
const scenes = d.escenas.map(e => ({
  elements: [
    { type: 'image', src: e.imagen_url, x: 0, y: 0, width: 1080, height: 1920, resize: 'cover', duration: -2, zoom: 2 },
    { type: 'voice', model: 'azure', voice: 'es-EC-LuisNeural', text: e.narracion }
  ]
}));
const body = { resolution: 'custom', width: 1080, height: 1920, quality: 'high', scenes,
  elements: [{ type: 'subtitles', language: 'es', settings: { style: 'classic', 'font-size': 80, position: 'mid-bottom-center', 'outline-color': '#000000', 'outline-width': 4, 'word-color': '#FFD700', 'line-color': '#FFFFFF' } }] };
return [{ json: { ...d, j2v_body: body } }];

const m = $input.first().json.movie || {};
const d = $('📦 Unir escenas + imágenes').first().json;
return [{ json: { ID: d.ID, ESTADO_CORTO: 'renderizado', VIDEO_URL_CORTO: m.url || '', TITULO_CORTO: d.titulo_video, DESC_CORTO: d.descripcion_seo, TAGS_CORTO: d.palabras_clave, HASHTAGS_CORTO: d.hashtags, FECHA_CORTO: new Date().toISOString().split('T')[0] } }];

